\label{lem:max-truncation}
Assume \hyperref[hyp:R]{\textup{(R)}}. For all $c,t>0$ and $L\ge1$ there are $\varepsilon,\delta>0$ and an integer $n$
with $n\ge L$ and $n\ge L/\min(\varepsilon,\delta)$ such that, for all large $N$,
\begin{equation}\label{eq:max-band-thm}
 \mathbb{P}^{*}\Bigl(\exists m\in[-1,1]^N:\
 \bigl|F^{\mathrm{band}}_n(m;\varepsilon,\delta)-F_{\mathrm{TAP}}(m)\bigr|\ge tN\Bigr)\le e^{-cN}.
\end{equation}

\label{lem:max-band}
Let $H$ be a real function on $[-1,1]^N$, $Z=2^{-N}\sum_{\sigma\in\{-1,1\}^N}e^{H(\sigma)}$ and
$G(\sigma)=2^{-N}e^{H(\sigma)}/Z$, and define $F^{\mathrm{band}}_n$ by \eqref{eq:max-band} with $H$
in place of $H_N$. Let $q\in[-1,1]$, $\varepsilon,\delta>0$, let $n\ge4/\min(\varepsilon,\delta)$ be
an integer and $\tau\in(0,\min(\varepsilon,\delta)/4]$. If $G^{\otimes2n}(A_{2n}(q,\tau))>0$, there
is $m\in[-1,1]^N$, the barycenter of $n$ points of $\{-1,1\}^N$, such that
$|q_m-q|<(1-q)/n+\tau$ and
\begin{equation}\label{eq:max-band-step}
 F^{\mathrm{band}}_n(m;\varepsilon,\delta)\ \ge\ \log Z+\frac1n\log G^{\otimes2n}\bigl(A_{2n}(q,\tau)\bigr).
\end{equation}

\label{lem:loc-monotone}
Assume \hyperref[hyp:H]{\textup{(H)}}\ and let $Q\in(0,1)$. If $(\mathsf{x},\eta)\in\mathcal A_Q$ and $\mathrm{glue}(\mathsf{x},\eta)$ is
nondecreasing on $[0,1)$, then $P(\mathrm{glue}(\mathsf{x},\eta))\ge P_{\zeta_f}$.

\label{lem:eq-obstacle}
Assume \hyperref[hyp:H]{\textup{(H)}}\ and let $\zeta_{\mathrm{P}}$ be a Parisi measure.
\begin{thmlist}
\item\label{lem:eq-obstacle-a} $\int\mathcal{O}_{\mathrm{P}}\,d\mu\ge\int\mathcal{O}_{\mathrm{P}}\,d\zeta_{\mathrm{P}}$ for every
 $\mu\in\mathcal{P}([0,1])$. Consequently $\int\mathcal{O}_{\mathrm{P}}\,d\zeta_{\mathrm{P}}=\min_{[0,1]}\mathcal{O}_{\mathrm{P}}$, and
 $\operatorname{supp}\zeta_{\mathrm{P}}\subsetC_{\mathrm{P}}$.
\item\label{lem:eq-obstacle-b} $\mathcal{O}_{\mathrm{P}}'(1)=\frac12\xi''(1)\bigl(1-\mathbb{E}\tanh^2X_1\bigr)>0$.
 Consequently $\min_{[0,1]}\mathcal{O}_{\mathrm{P}}<0=\mathcal{O}_{\mathrm{P}}(1)$, and $C_{\mathrm{P}}$ is a nonempty compact subset of $[0,1)$.
\end{thmlist}

\label{lem:eq-zero}
Assume \hyperref[hyp:H]{\textup{(H)}}. For every Parisi measure $\zeta_{\mathrm{P}}$, $\mathcal{O}_{\mathrm{P}}(0)=\min_{[0,1]}\mathcal{O}_{\mathrm{P}}$; that is,
$0\inC_{\mathrm{P}}$.

\label{lem:eq-gap}
Assume \hyperref[hyp:H]{\textup{(H)}}. Let $Q\in(0,1)\setminusC_{\mathrm{P}}$ and $\varepsilon\in(0,1]$, and take the glued data
\[
 \mathsf{x}=\bar{\zeta_{\mathrm{P}}}+\varepsilon\ \text{ on }[0,Q),\qquad \eta=\operatorname{Shift}_Q\zeta_{\mathrm{P}}\in\mathcal{P}([Q,1]).
\]
Then $\mathsf{x}$ is nondecreasing with values in $[\varepsilon,2]$, and
\begin{equation}\label{eq:eq-gap}
 P\bigl(\mathrm{glue}(\mathsf{x},\eta)\bigr)\lef_{\mathrm{eq}}-\varepsilon\bigl(\mathcal{O}_{\mathrm{P}}(Q)-\min\mathcal{O}_{\mathrm{P}}\bigr)+K\varepsilon^2 .
\end{equation}

\label{lem:pde-coef}
Let $c_1,c_2$ be step coefficients on $[t_0,t_1)$ with values in $[0,G]$, let $\psi\in\mathcal T_G$,
$W_i=W[c_i,\psi]$ and $v_i=\partial_yW_i$. For $y\in\mathbb{R}$ let $X^i$ solve \eqref{eq:pde-ac} for
$c_i$ from $(t_0,y)$, and put $\Gamma_i(r)=\mathbb{E}\,v_i(r,X^i_r)^2$. Then
\begin{equation}\label{eq:pde-coef}
 \frac12\int_{t_0}^{t_1}\xi''(c_2-c_1)\Gamma_1\,dr
 \ \le\ W_2(t_0,y)-W_1(t_0,y)\ \le\
 \frac12\int_{t_0}^{t_1}\xi''(c_2-c_1)\Gamma_2\,dr .
\end{equation}
In particular $|W_2-W_1|\le\frac12\xi''(1)\|c_1-c_2\|_{L^1}$ on $[t_0,t_1]\times\mathbb{R}$.

\label{cor:pde-step}
Let $c,c_1,c_2$ be step coefficients on $[0,1)$ with values in $[0,G]$.
\begin{thmlist}
\item\label{cor:pde-step-a} \textup{(Sandwich.)}
 $DP(c_1)[c_2-c_1]\le P(c_2)-P(c_1)\le DP(c_2)[c_2-c_1]$.
\item\label{cor:pde-step-b} \textup{(Convexity.)} $P$ is convex.
\item\label{cor:pde-step-c} \textup{(Lipschitz bound.)}
 $|P(c_1)-P(c_2)|\le\frac12\xi''(1)\|c_1-c_2\|_{L^1}$.
\item\label{cor:pde-step-d} \textup{(Second moments and field laws.)}
 $\sup_t|\Gamma_{c_1}-\Gamma_{c_2}|(t)\le L_\Gamma\|c_1-c_2\|_{L^1}$, and, if $X^{c_1}$ and $X^{c_2}$
 are driven by the same Brownian motion,
 $\mathbb{E}|v_{c_1}(t,X^{c_1}_t)-v_{c_2}(t,X^{c_2}_t)|\le L_M\|c_1-c_2\|_{L^1}$ for every $t$.
\item\label{cor:pde-step-e} \textup{(Second order.)} For every step function $h$ and $\varepsilon\in\mathbb{R}$
 such that $c+\varepsilon h$ takes values in $[0,G]$,
 \[
  P(c+\varepsilon h)\le P(c)+\varepsilon\,DP(c)[h]+K\varepsilon^2\|h\|_{L^1}^2,\qquad
  K:=\tfrac12\xi''(1)L_\Gamma .
 \]
\end{thmlist}
The constant $K$ depends only on $G$, $\xi'(1)$ and $\xi''(1)$.

\label{lem:var-tangent}
Assume \hyperref[hyp:H]{\textup{(H)}}. Let $\theta\in(0,1)$ and $\zeta'\in\mathcal{P}([0,1])$ with $\zeta'(\{0\})\ge\theta$,
let $X'$ be the Auffinger--Chen process of $\zeta'$, and put
$L'_q=\operatorname{Law}(\Phi_{\zeta',x}(q,X'_q))$ for $q\in[0,1]$. Let $g\in C^2([-1,1])$ with
$\|g'\|_\infty\le1$, and let $|s|\le(2\|g''\|_\infty)^{-1}$. Put $C_2=1+L_\psi$, which depends
only on $\xi'(1)$ and $\xi''(1)$.
\begin{thmlist}
\item\label{lem:var-tangent-a} For every $Q\in[0,1)$,
 \begin{equation}\label{eq:var-tangent}
  P_s\bigl(\bar{\zeta'}|_{[0,Q)},\operatorname{Shift}_Q\zeta'\bigr)\le P_{\zeta'}+s\int g\,dL'_Q+C_2s^2 .
 \end{equation}
\item\label{lem:var-tangent-b} For every $Q\in[0,1)$, $\rho'\in(0,1-Q]$, $\varepsilon_A>0$ and
 $N\ge1$ there is a random variable $\mathcal T$ with
 $\mathbb{E} e^{\theta\mathcal T}\le(N+1)e^{N\theta C_R\rho'}$ such that
 \begin{multline*}
  \sup\Bigl\{F_{\mathrm{TAP}}(m)+s\sum_{i=1}^Ng(m_i):\ m\in[-1,1]^N,\ q_m\in[Q,Q+\rho']\Bigr\}\\
  \le N\Bigl[P_{\zeta'}+s\int g\,dL'_Q+C_2s^2+\varepsilon_A\Bigr]+\mathcal T .
 \end{multline*}
\end{thmlist}

\label{lem:matrix-comparison}
Let $a\ge0$ and let $D_N$ be a deterministic real diagonal $N\times N$ matrix.
\begin{thmlist}
\item\label{lem:matrix-comparison-a} \textup{(Comparison.)}
 \begin{equation}\label{eq:matrix-comparison}
  \mathbb{E}\lambda_{\max}\bigl(\sqrt a\,W_N-D_N\bigr)
  \le\inf_{t<\min_iD_{N,ii}}\Bigl\{-t+\frac aN\sum_{i\le N}\frac1{D_{N,ii}-t}\Bigr\}.
 \end{equation}
 In particular $\mathbb{E}\lambda_{\max}(W_N)\le2$, and $\mathbb{P}(\|W_N\|>2+\delta)\le2e^{-\delta^2N/4}$ for
 every $\delta>0$.
\item\label{lem:matrix-comparison-b} \textup{(Resolvent.)} For $z=E+\mathrm i\varepsilon$ with
 $\varepsilon>0$ let $G_N(z)=(D_N-\sqrt a\,W_N-z)^{-1}$, $m_N(z)=N^{-1}\operatorname{tr} G_N(z)$ and
 $\bar m_N(z)=\mathbb{E} m_N(z)$. For deterministic $v,w\in\mathbb{R}^N$,
 \begin{equation}\label{eq:matrix-resolvent-var}
  \mathbb{E}\bigl|v^{\mathsf T}(G_N-\mathbb{E} G_N)w\bigr|^2\le\frac{4a|v|^2|w|^2}{N\varepsilon^4},\qquad
  \mathbb{E}|m_N-\bar m_N|^2\le\frac{4a}{N^2\varepsilon^4}.
 \end{equation}
 Moreover $(\mathbb{E} G_N)_{ij}=0$ for $i\ne j$, and
 \begin{equation}\label{eq:matrix-approx-dyson}
  \mathbb{E} G_{N,ii}=\frac1{D_{N,ii}-z-a\bar m_N}+O\Bigl(\frac1N\Bigr),\qquad
  \bar m_N=\frac1N\sum_{i\le N}\frac1{D_{N,ii}-z-a\bar m_N}+O\Bigl(\frac1N\Bigr),
 \end{equation}
 where the errors are bounded by $C_{a,\varepsilon}/N$, uniformly in $i$ and in $D_N$.
\item\label{lem:matrix-comparison-c} \textup{(Resolvent equation.)} For $\rho\in\mathcal{P}(\mathbb{R})$ and
 $z\in\mathbb{C}^+$ the equation
 \begin{equation}\label{eq:matrix-dyson}
  m=\int\frac{\rho(dD)}{D-z-am},\qquad\operatorname{Im}m>0,
 \end{equation}
 has at most one solution. If $\operatorname{ESD}(D_N)\to\rho$ weakly, it has a solution $m(z)$, and
 $\bar m_N(z)\to m(z)$ and $m_N(z)\to m(z)$ in probability.
\end{thmlist}

\label{lem:matrix-third}
Assume \hyperref[hyp:R]{\textup{(R)}}\ and put $C_H=2\xi''(1)+4\xi'''(1)+\xi''''(1)$.
\begin{thmlist}
\item\label{lem:matrix-third-a} For $y\in[-1,1]^N$ with $r=q_y$ and every symmetric $N\times N$
 matrix $S$,
 \begin{equation}\label{eq:matrix-hess-cov}
  \operatorname{Var}\operatorname{tr}\bigl(S\,\nabla^2H_N(y)\bigr)=\frac{2\xi''(r)}N\operatorname{tr} S^2+\frac{4\xi'''(r)}{N^2}|Sy|^2
  +\frac{\xi''''(r)}{N^3}\bigl(y^{\mathsf T}Sy\bigr)^2\le\frac{C_H}N\operatorname{tr} S^2 .
 \end{equation}
 Consequently, at a fixed $y$,
 \[
  \nabla^2H_N(y)\overset{d}{=}\sqrt{\xi''(r)}\,W_N+\frac1N\bigl(y\gamma^{\mathsf T}+\gamma y^{\mathsf T}\bigr)
  +\frac{Z}{N^{3/2}}\,yy^{\mathsf T},
 \]
 with $W_N$, $\gamma\sim N(0,\xi'''(r)I_N)$ and $Z\sim N(0,\xi''''(r))$ independent. The last two
 terms have rank at most two.
\item\label{lem:matrix-third-b} For every $M>0$ there are $C^H_2,C^H_3$, depending only on $\xi$ and
 $M$, such that for every $N$
 \begin{equation}\label{eq:matrix-sup}
 \begin{gathered}
  \mathbb{P}\Bigl(\sup_{y\in[-1,1]^N}\|\nabla^2H_N(y)\|>C^H_2\Bigr)\le e^{-MN},\\
  \mathbb{P}\Bigl(\sup_{y\in[-1,1]^N}\|D^3H_N(y)\|>\frac{C^H_3}{\sqrt N}\Bigr)\le e^{-MN}.
 \end{gathered}
 \end{equation}
\end{thmlist}

\label{rem:matrix-conditional}
Appendix~\ref{app:kr} uses the third-derivative bound for $H_N$ conditioned on its value and its
gradient at a point. Gaussian conditioning decreases variances and increment variances, so the
centred part of the conditioned field satisfies Lemma~\ref{lem:matrix-third}\ref{lem:matrix-third-b}
with the same constants. Its conditional mean is a separate matter, which Appendix~\ref{app:kr}
treats under its hypothesis of two active degrees. Theorem~\ref{thm:struct} uses only the
unconditional bounds of Lemma~\ref{lem:matrix-third}, which hold for every $\xi$ satisfying \hyperref[hyp:R]{\textup{(R)}},
single-degree covariances included.

\label{lem:matrix-correction}
Assume $\xi\in\mathcal{C}$. For all $\alpha,\beta\in\mathcal{P}([0,1])$, $r,r'\in[0,1]$ and
$\mu,\mu'\in\mathcal{P}([-1,1])$:
\begin{thmlist}
\item\label{lem:matrix-correction-a} $|\Phi^{*}_\alpha(r,m)|\le C_*$ for every $m\in[-1,1]$;
\item\label{lem:matrix-correction-b}
 $|V_\alpha(r,\mu)-V_\alpha(r',\mu')|\le L_1|r-r'|+L_2\,\varrho\bigl(W_1(\mu,\mu')\bigr)$, and the same
 holds for $V_{\mathrm{TAP}}$;
\item\label{lem:matrix-correction-c}
 $|V_\alpha(r,\mu)-V_\beta(r,\mu)|\le\xi''(1)\int_r^1|\bar{\alpha}(t)-\bar{\beta}(t)|\,dt$.
\end{thmlist}

\label{lem:kr-contact}
\leavevmode
\begin{thmlist}
\item\label{lem:kr-contact-a} $\theta\in(0,1)$, $\zeta(\{0\})=\theta$ and $\zeta((0,q))=0$, so that
 $\bar{\zeta}(t)=\theta$ for $t\in[0,q)$. Moreover $\Sigma(f)=\theta(P_\zeta-f)$.
\item\label{lem:kr-contact-b} $q\in(0,1)$, $\mathcal{O}_\zeta(r)>\mathcal{O}_\zeta(q)$ for $r\in(0,q)$,
 $\Gamma_{\zeta}(q)=q$, and $\Delta_0=1-a\mathbb{E}_0U^2=2\mathcal{O}_\zeta''(q)/a\ge0$.
\item\label{lem:kr-contact-c} \textup{(Level identity.)}
 $f=P_\zeta+\theta\bigl(\mathcal{O}_\zeta(0)-\mathcal{O}_\zeta(q)\bigr)$.
\item\label{lem:kr-contact-d} \textup{(Regularity.)} For every $t\in[0,1]$, $\Phi_x(t,\cdot)$ is an
 odd, strictly increasing bijection of $\mathbb{R}$ onto $(-1,1)$, and $0<\Phi_{xx}\le1$. There are
 $0<c_1\le C_1$ and $C_{34}$, depending only on $\xi'(1)$, with
 \[
  c_1e^{-2|b|}\le\Phi_{xx}(t,b)\le C_1e^{-2|b|},\qquad
  |\Phi_{xxx}(t,b)|+|\Phi_{xxxx}(t,b)|\le C_{34}\Phi_{xx}(t,b),
 \]
 for all $(t,b)\in[0,1]\times\mathbb{R}$.
\item\label{lem:kr-contact-e} \textup{(Plateau law.)} The law $\pi_0$ has the density
 \begin{equation}\label{eq:kr-law}
  \frac{d\pi_0}{d\mathcal N(0,c)}(b)=\exp\bigl\{\theta\bigl[\Phi(q,b)-\Phi(0,0)\bigr]\bigr\}
 \end{equation}
 with respect to the centred Gaussian law of variance $c=\xi'(q)$. It is positive and has Gaussian
 tails, and for every $C^1$ function $F$ with $|F|+|F'|\le C(1+e^{C|b|})$,
 \begin{equation}\label{eq:kr-ward}
  \mathbb{E}_0\bigl[bF(b)/c\bigr]=\mathbb{E}_0\bigl[F'(b)+\theta M(b)F(b)\bigr].
 \end{equation}
\end{thmlist}

\label{lem:kr-energy}
$\det S_0>0$, and
\begin{equation}\label{eq:kr-collar}
 1-A(r)\ge(1-r/q)^2\quad(0\le r\le q),\qquad qA''(q)<0 .
\end{equation}
At a point $x$ with $q_x=q$, the conditional variance of $H_N(x)$ given $\nablaH_N(x)$ is
$N\sigma_H^2$, where
\begin{equation}\label{eq:kr-sigmaH}
 \sigma_H^2=\xi(q)-\frac{qc^2}{c+aq}=\frac{\det S_0}{s_2}>0 .
\end{equation}

\label{lem:kr-comparison}
\leavevmode
\begin{thmlist}[beginpenalty=10000]
\item\label{lem:kr-comparison-a} \textup{(Exact slices.)} Let $x\in(-1,1)^N$ with $q_x=q$ and
 condition on \eqref{eq:kr-conditioning}. Then, for $0<r<q$,
 \begin{equation}\label{eq:kr-exact-comparison}
  \frac1N\mathbb{E}_{\rm cond}\sup\bigl\{F_\zeta(y)-F_\zeta(x):\ y\in[-1,1]^N,\ q_y=q,\ R(x,y)=r\bigr\}
  \le J_{\pi_x,h}(r),
 \end{equation}
 where the supremum over the empty set is $-\infty$.
\item\label{lem:kr-comparison-b} \textup{(Windows.)} Fix a compact interval $I\subset(0,q)$, a law
 $\pi$ as above and $h\in\mathbb{R}$. For $\omega>0$, consider anchors with $|q_x-q|\le\omega$,
 $W_2(\pi_x,\pi)\le\omega$, conditioned on $H_N(x)=Nh'$ with $|h'-h|\le\omega$ and on the gradient
 value given by $\nabla F_\zeta(x)=0$, and replace the competitor constraints by $|q_y-q|\le\omega$
 and $|R(x,y)-r|\le\omega$. Then the left side of \eqref{eq:kr-exact-comparison} is at most
 $J_{\pi,h}(r)+o_\omega(1)$, where $o_\omega(1)$ depends only on $I$, $\xi$, $\zeta$, $\pi$ and $h$,
 tends to zero as $\omega\downarrow0$, and is uniform in $N$, $r\in I$ and the conditional data.
\item\label{lem:kr-comparison-c} \textup{(Gap.)} For $0<r<q$,
 \begin{equation}\label{eq:kr-baseline-J}
  J_{\pi_0,h_0}(r)=-\theta\bigl(\mathcal{O}_\zeta(r)-\mathcal{O}_\zeta(q)\bigr).
 \end{equation}
 If $\Delta_0=0$, there is $L_J$ such that, for every $L\ge L_J$ in \eqref{eq:kr-heta} and every
 $\eta\in(0,\eta_0]$,
 \begin{equation}\label{eq:kr-tilted-gap}
  J_{\pi_\eta,h_\eta}(r)\le-\theta\bigl(\mathcal{O}_\zeta(r)-\mathcal{O}_\zeta(q)\bigr)-\eta\,(q-r)^2,
  \qquad 0<r<q .
 \end{equation}
\end{thmlist}

\label{lem:kr-correction}
Let $0\le\eta\le\eta_0$, with $\eta=0$ if $\Delta_0>0$, let $x\in(-1,1)^N$, and let
$w=W_2(\pi_x,\pi_\eta)\le2$. Then
$W_1(\mu_x,M_\#\pi_\eta)\le w$, $|q_x-q|\le2w$, and
\begin{thmlist}
\item\label{lem:kr-correction-a}
 $|V_\zeta(q_x,\mu_x)-V_\zeta(q,M_\#\pi_\eta)|\le C_V\varrho(w)$;
\item\label{lem:kr-correction-b} $0\le\bigl(F_\zeta(x)-F_{\mathrm{TAP}}(x)\bigr)/N\le C_V\bigl(\eta+\varrho(w)\bigr)$.
\end{thmlist}
Moreover the value at the selected data,
\begin{equation}\label{eq:kr-feta}
 f_\eta=h_\eta+V_\zeta(q,M_\#\pi_\eta),\qquad\text{satisfies}\qquad
 f_0=f,\qquad |f_\eta-f|\le(L+C_V)\,\eta .
\end{equation}

\label{lem:kr-marks}
Let $x\in(-1,1)^N$ satisfy~\ref{step:kr-ret2}.
\begin{thmlist}
\item\label{lem:kr-marks-a} If $x$ satisfies~\ref{step:kr-ret4}, then
 $\langle\nabla F_\zeta(y)-\nabla F_\zeta(y'),y-y'\rangle\le-g_\eta|y-y'|^2$ for all $y,y'$ in
 $B(x)=\{z\in(-1,1)^N:|z-x|\le\rho_\eta\sqrt N\}$.
\item\label{lem:kr-marks-b} If $|h'-h|\le N^{-2}$ and $N\ge\omega_c^{-1/2}$, then
 \[
  \mathbb{P}_{x,h'}\bigl(\text{\ref{step:kr-ret5} fails}\bigr)\le\frac q{\omega_c}
  \exp\Bigl\{-\frac{N\gamma^2}{32\,\xi(1)}\Bigr\}.
 \]
\item\label{lem:kr-marks-c} $\displaystyle\lim_{w\downarrow0}\limsup_{N\to\infty}\sup_{x,h'}
 \mathbb{P}_{x,h'}\bigl(\text{\ref{step:kr-ret4} fails}\bigr)=0$, the supremum being over $x$
 satisfying~\ref{step:kr-ret2} and $|h'-h|\le N^{-2}$.
\end{thmlist}

\label{lem:kr-normalization}
$\Sigma_{\rm KR}(\pi_0,h_0)=\Sigma(f)$, and there is $C_\Sigma$ with
$|\Sigma_{\rm KR}(\pi_\eta,h_\eta)-\Sigma(f)|\le C_\Sigma\eta$ for every admissible $\eta$.

\label{lem:kr-susywindow}
For $0<\varepsilon\le\varepsilon_0$ and $x\in\mathcal W_\varepsilon$:
\begin{thmlist}
\item\label{lem:kr-susywindow-a} $N^{-1}|b|^2\le C$, $\max_i|b_i|\le C\sqrt N$ and
 $\max_iu(q_x,x_i)^{-1}\le Ce^{C\sqrt N}$;
\item\label{lem:kr-susywindow-b} $|N^{-1}\sum_i\log U(b_i)-\mathbb{E}_0\log U|\le C_{34}\varepsilon$ and
 $|N^{-1}\sum_i\Phi(q,b_i)-\mathbb{E}_0\Phi(q,b)|\le\varepsilon$;
\item\label{lem:kr-susywindow-c} $|\chi_x-\chi_0|+|k_x-k_0|\le C\varepsilon$ and
 $N^{-1}\bigl||b^{(q_x)}|^2-|b|^2\bigr|\le C\varepsilon$;
\item\label{lem:kr-susywindow-d} $|V_\zeta(q_x,\mu_x)-(f-h_0)|\le C_V\varrho(\varepsilon)$.
\end{thmlist}

\label{lem:kr-susystructure}
Let $x\in(-1,1)^N$ with $r=q_x\in\mathcal J_0$ not an atom of $\zeta$, and $h\in\mathbb{R}$. Conditionally on
$\nablaH_N(x)=\mathbf g(x)$ and $H_N(x)=Nh$, the matrix $\nabla^2F_\zeta(x)$ has the law of
$\mathbf A=\mathbf A_0+\mathsf K\mathbf Y$, where $\mathbf Y$ is a standard Gaussian vector,
$\mathsf K$ is linear and $\mathbf A_0$ is a deterministic symmetric matrix, and:
\begin{thmlist}
\item\label{lem:kr-susystructure-a} there are an orthogonal matrix $O$ with first column $x/|x|$ and a
 GOE matrix $W'$ whose independent entries are coordinates of $\mathbf Y$ such that the compression
 of $\mathbf A$ to $x^\perp$ equals that of $\sqrt{a_r}\,W-\mathsf D_x$, where $W=OW'O^{\mathsf T}$ is a GOE
 matrix;
\item\label{lem:kr-susystructure-b} $\|\mathsf K\mathbf y\|_{\rm HS}^2\le C_{\mathsf K}N^{-1}|\mathbf y|^2$ for every
 $\mathbf y$;
\item\label{lem:kr-susystructure-c} $\|\mathbf A_0\|\le\max_iu(r,x_i)^{-1}+C(1+|h|+|b^{(r)}|/\sqrt N)$.
\end{thmlist}

\label{lem:nc-jets}
For every $k\ge0$ there is $C_k<\infty$, and there is $C<\infty$, such that the following hold for
all $\xi,\tilde\xi\in\mathcal K$ and $\zeta,\tilde\zeta\in\mathcal{P}([0,1])$.
\begin{thmlist}[beginpenalty=10000]
\item\label{lem:nc-jets-a} $\partial_x^j\Phi$ is continuous on $[0,1]\times\mathbb{R}$ for every
 $j\ge0$, $\Phi(t,\cdot)$ is even, $|u|\le1$, $0<\partial_xu\le1$, and
 $\sup_{[0,1]\times\mathbb{R}}|\partial_x^ku|\le C_k$.
\item\label{lem:nc-jets-b} \textup{(Jet stability.)}
 \begin{equation}\label{eq:nc-jet}
  \|\partial_x^k(u-\tilde u)\|_\infty
  \le C_k\bigl(\|a-\tilde a\|_{L^1}+\|a\alpha-\tilde a\tilde\alpha\|_{L^1}\bigr).
 \end{equation}
\item\label{lem:nc-jets-c} \textup{(Small times.)} $\mathbb{E} X_t^2\le2\|a\|_\infty t+2\|a\|_\infty^2t^2$
 for $t\in[0,1]$.
\item\label{lem:nc-jets-d} \textup{(Continuity in the pair.)}
 \begin{equation}\label{eq:nc-continuity}
  \sup_{[0,1]}\bigl(|\Gamma-\tilde\Gamma|+|\Gamma'-\tilde\Gamma'|\bigr)
  +\bigl|P^\xi_\zeta-P^{\tilde\xi}_{\tilde\zeta}\bigr|
  \le C\bigl(\|a-\tilde a\|_\infty+\|a\alpha-\tilde a\tilde\alpha\|_{L^1}\bigr).
 \end{equation}
\end{thmlist}

\label{lem:nc-plateau}
Let $\xi\in\mathcal K$ and $\zeta\in\mathcal{P}([0,1])$.
\begin{thmlist}
\item\label{lem:nc-plateau-a} $\Gamma\in C^1([0,1])$ with $\Gamma'(t)=\xi''(t)\,\mathbb{E} U_t^2$;
 moreover $\Gamma(0)=0$, $U_0=\Phi_{xx}(0,0)>0$ and $V_0=0$.
\item\label{lem:nc-plateau-b} Let $I$ be a plateau of $\zeta$ with height $\omega$. Then
 $\Gamma\in C^3(I)$ and, on $I$, with $U=U_t$, $V=V_t$, $W=W_t$,
 \begin{align}
  \Gamma''&=\xi'''\,\mathbb{E} U^2+\xi''^2\,\mathbb{E}\bigl(V^2-2\omega U^3\bigr),\label{eq:nc-second}\\
  \Gamma'''&=\xi''''\,\mathbb{E} U^2+3\xi''\xi'''\,\mathbb{E}\bigl(V^2-2\omega U^3\bigr)
   +\xi''^3\,\mathbb{E}\bigl(W^2-12\omega UV^2+6\omega^2U^4\bigr).\label{eq:nc-third}
 \end{align}
 For fixed $\omega$ the right sides are continuous functions of $t\in[0,1]$. In particular, at an
 endpoint of $I$ the one-sided derivative of $\Gamma'$ from inside $I$ exists and equals the right
 side of \eqref{eq:nc-second} there.
\item\label{lem:nc-plateau-c} For $t\in[0,1)$ the right derivative $\Gamma''(t+)$ of $\Gamma'$ at
 $t$ exists and equals the right side of \eqref{eq:nc-second} at $t$ with $\omega=\zeta([0,t])$;
 for $t\in(0,1]$ the left derivative $\Gamma''(t-)$ exists and equals the same expression with
 $\omega=\zeta([0,t))$. In particular, for $t\in(0,1)$,
 \begin{equation}\label{eq:nc-jump}
  \Gamma''(t-)-\Gamma''(t+)=2\,\xi''(t)^2\,\zeta(\{t\})\,\mathbb{E} U_t^3 .
 \end{equation}
\end{thmlist}

\label{lem:nc-near}
There are $t_{\mathrm c}\in(0,1)$ and $\varepsilon_2>0$ such that, for every $\xi\in\mathcal K$
with $d(\xi)<\varepsilon_2$ and every $\zeta\in\mathcal{P}([0,1])$ with $m_1(\zeta)<\varepsilon_2$, the
following hold.
\begin{thmlist}
\item\label{lem:nc-near-a} \textup{(Third derivative.)} For every plateau $I$ of $\zeta$,
 \begin{equation}\label{eq:nc-third-positive}
  \Gamma'''(t)\ge2\qquad\text{for every } t\in I\cap(0,t_{\mathrm c}).
 \end{equation}
\item\label{lem:nc-near-b} \textup{(Below the diagonal.)} $\Gamma(t)<t$ and $\mathcal{O}'(t)>0$ for
 every $t\in[t_{\mathrm c},1]$.
\end{thmlist}

\label{lem:nc-contact}
Let $\xi\in\mathcal K$ and $\zeta\in\mathcal{P}([0,1])$. If $\mathcal{O}$ has a local minimum at
$t\in(0,1)$, then
\begin{equation}\label{eq:nc-contact}
 \Gamma(t)=t,\qquad\Gamma'(t)\le1 .
\end{equation}
If $\mathcal{O}$, as a function on $[0,1]$, has a local minimum at $0$, then \eqref{eq:nc-contact} holds at
$t=0$.

\label{lem:nc-confine}
For every $\varepsilon>0$ there is $\varepsilon_3>0$ such that $m_1(\zeta^\xi_\theta)<\varepsilon$
for every $\xi\in\mathcal K$ with $d(\xi)<\varepsilon_3$ and every $\theta\in[0,1]$.

\label{lem:moments-guerra}
Assume \hyperref[hyp:H]{\textup{(H)}}. For every $N\ge1$, every $\theta\in(0,1)$ and every $\alpha\in\mathcal{P}([0,1])$
with $\alpha(\{0\})\ge\theta$,
\begin{equation}\label{eq:moments-guerra}
 \frac1{N\theta}\log\mathbb{E}Z_N^\theta\le P_\alpha .
\end{equation}
Consequently $N^{-1}\log\mathbb{E}Z_N^\theta\le\Lambda(\theta)$ for every $N\ge1$ and every
$\theta\in(0,1)$.
